// Hex viewer (hexyl-compatible)
// Reimplemented from behavioral observation.

use std::env;
use std::fs::File;
use std::io::{self, BufWriter, Read, Seek, SeekFrom, Write, IsTerminal};
use std::process::ExitCode;

mod args;
mod byte;
mod cp437;
mod cp1047;
mod color;
mod completions;
mod parse_num;
mod hex_dump;

use args::{parse_args, Args, Base, BorderStyle, CharTable, ColorScheme, ColorWhen, Endianness};

fn main() -> ExitCode {
    let argv: Vec<String> = env::args().collect();
    let parsed = match parse_args(&argv) {
        Ok(a) => a,
        Err(args::ArgsError::Usage(msg)) => {
            // Usage / clap-style error
            eprint!("{}", msg);
            return ExitCode::from(2);
        }
        Err(args::ArgsError::Help(msg)) => {
            print!("{}", msg);
            return ExitCode::from(0);
        }
        Err(args::ArgsError::Version(msg)) => {
            print!("{}", msg);
            return ExitCode::from(0);
        }
    };

    match run(parsed) {
        Ok(()) => ExitCode::from(0),
        Err(e) => {
            let stderr = io::stderr();
            let mut err = stderr.lock();
            // Write the chain of causes
            let _ = writeln!(err, "Error: {}", e.primary);
            for (i, cause) in e.causes.iter().enumerate() {
                if e.causes.len() == 1 {
                    let _ = writeln!(err);
                    let _ = writeln!(err, "Caused by:");
                    let _ = writeln!(err, "    {}", cause);
                } else {
                    if i == 0 {
                        let _ = writeln!(err);
                        let _ = writeln!(err, "Caused by:");
                    }
                    let _ = writeln!(err, "    {}: {}", i, cause);
                }
            }
            ExitCode::from(1)
        }
    }
}

pub struct MyError {
    pub primary: String,
    pub causes: Vec<String>,
}

impl MyError {
    pub fn new(s: impl Into<String>) -> Self {
        MyError { primary: s.into(), causes: Vec::new() }
    }
    pub fn with_causes(s: impl Into<String>, causes: Vec<String>) -> Self {
        MyError { primary: s.into(), causes }
    }
}

impl<E: std::fmt::Display> From<E> for MyError {
    fn from(e: E) -> Self {
        MyError::new(format!("{}", e))
    }
}

fn run(args: Args) -> Result<(), MyError> {
    // Special modes
    if args.print_color_table {
        return print_color_table(&args);
    }
    if let Some(shell) = &args.completion {
        let text = completions::completion_for(shell);
        io::stdout().write_all(text.as_bytes()).ok();
        return Ok(());
    }

    // Determine color state
    let color_active = determine_color(&args);
    let cfg = color::ColorConfig::from_env(color_active);

    // Open input
    let (mut reader, is_file, total_len): (Box<dyn ReadSeek>, bool, Option<u64>) = match &args.file {
        Some(path) => {
            let f = File::open(path).map_err(|e| MyError::new(format!("{}", e)))?;
            let meta = f.metadata().ok();
            let len = meta.map(|m| m.len());
            (Box::new(f), true, len)
        }
        None => (Box::new(SeekableReader::new(io::stdin())), false, None),
    };

    // Apply skip
    if args.skip != 0 {
        let target = if args.skip < 0 {
            let end = reader.seek(SeekFrom::End(0))
                .map_err(|_| MyError::new("Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe)."))?;
            let off = args.skip;
            let as_u64 = (-off) as u64;
            if as_u64 > end {
                return Err(MyError::new("Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe)."));
            }
            end - as_u64
        } else {
            args.skip as u64
        };
        reader.seek(SeekFrom::Start(target))
            .map_err(|_| MyError::new("Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe)."))?;
    }
    let base_offset = if args.skip < 0 {
        // Calculate actual base from end
        if let Some(len) = total_len {
            let off = args.skip;
            let as_u64 = (-off) as u64;
            len.saturating_sub(as_u64)
        } else {
            // Shouldn't happen for stdin
            0
        }
    } else {
        args.skip as u64
    };

    // Handle length limit - read bytes
    let data = read_all_bytes(&mut reader, args.length)?;
    drop(reader);

    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());

    if args.include {
        hex_dump::write_include(&mut out, &data, args.file.as_deref(), is_file)?;
        out.flush().ok();
        return Ok(());
    }

    hex_dump::write_dump(&mut out, &data, base_offset, &args, &cfg)?;
    out.flush().ok();
    Ok(())
}

pub trait ReadSeek: Read + Seek {}
impl<T: Read + Seek> ReadSeek for T {}

// Wrap Read with in-memory buffer that allows seek - for stdin
struct SeekableReader<R: Read> {
    buf: Vec<u8>,
    pos: u64,
    inner: R,
    exhausted: bool,
}
impl<R: Read> SeekableReader<R> {
    fn new(r: R) -> Self {
        SeekableReader { buf: Vec::new(), pos: 0, inner: r, exhausted: false }
    }
    fn ensure_read_to(&mut self, end: u64) -> io::Result<()> {
        while (self.buf.len() as u64) < end && !self.exhausted {
            let mut tmp = [0u8; 8192];
            match self.inner.read(&mut tmp) {
                Ok(0) => { self.exhausted = true; break; }
                Ok(n) => self.buf.extend_from_slice(&tmp[..n]),
                Err(e) => return Err(e),
            }
        }
        Ok(())
    }
    fn read_all_inner(&mut self) -> io::Result<()> {
        if !self.exhausted {
            let mut tmp = [0u8; 8192];
            loop {
                match self.inner.read(&mut tmp) {
                    Ok(0) => { self.exhausted = true; break; }
                    Ok(n) => self.buf.extend_from_slice(&tmp[..n]),
                    Err(e) => return Err(e),
                }
            }
        }
        Ok(())
    }
}
impl<R: Read> Read for SeekableReader<R> {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        // Read from buffer if available
        let need = buf.len();
        self.ensure_read_to(self.pos + need as u64)?;
        let avail = self.buf.len().saturating_sub(self.pos as usize);
        let to_copy = avail.min(need);
        if to_copy > 0 {
            buf[..to_copy].copy_from_slice(&self.buf[self.pos as usize..self.pos as usize + to_copy]);
            self.pos += to_copy as u64;
        }
        Ok(to_copy)
    }
}
impl<R: Read> Seek for SeekableReader<R> {
    fn seek(&mut self, pos: SeekFrom) -> io::Result<u64> {
        match pos {
            SeekFrom::Start(n) => {
                self.pos = n;
                Ok(self.pos)
            }
            SeekFrom::End(offset) => {
                // For stdin, we must read all
                self.read_all_inner()?;
                let len = self.buf.len() as i64;
                let np = len + offset;
                if np < 0 {
                    return Err(io::Error::new(io::ErrorKind::InvalidInput, "seek before start"));
                }
                self.pos = np as u64;
                Ok(self.pos)
            }
            SeekFrom::Current(offset) => {
                let np = self.pos as i64 + offset;
                if np < 0 {
                    return Err(io::Error::new(io::ErrorKind::InvalidInput, "seek before start"));
                }
                self.pos = np as u64;
                Ok(self.pos)
            }
        }
    }
}

fn read_all_bytes<R: Read>(r: &mut R, limit: Option<u64>) -> io::Result<Vec<u8>> {
    let mut buf = Vec::new();
    match limit {
        Some(lim) => {
            let mut taken = r.take(lim);
            taken.read_to_end(&mut buf)?;
        }
        None => { r.read_to_end(&mut buf)?; }
    }
    Ok(buf)
}

fn determine_color(args: &Args) -> bool {
    if args.plain {
        return false;
    }
    match args.color {
        ColorWhen::Never => false,
        ColorWhen::Always => {
            if std::env::var_os("NO_COLOR").is_some() {
                false
            } else {
                true
            }
        }
        ColorWhen::Force => true,
        ColorWhen::Auto => {
            if std::env::var_os("NO_COLOR").is_some() { false }
            else { io::stdout().is_terminal() }
        }
    }
}

fn print_color_table(args: &Args) -> Result<(), MyError> {
    let active = determine_color(args);
    let cfg = color::ColorConfig::from_env(active);
    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());

    writeln!(out, "hexyl color reference:")?;
    writeln!(out)?;
    // Null
    cfg.null.apply(&mut out)?;
    write!(out, "⋄ NULL bytes (0x00)\n")?;
    cfg.reset(&mut out)?;
    // Printable
    cfg.printable.apply(&mut out)?;
    write!(out, "a ASCII printable characters (0x20 - 0x7E)\n")?;
    cfg.reset(&mut out)?;
    // Whitespace
    cfg.whitespace.apply(&mut out)?;
    write!(out, "_ ASCII whitespace (0x09 - 0x0D, 0x20)\n")?;
    cfg.reset(&mut out)?;
    // Other
    cfg.other.apply(&mut out)?;
    write!(out, "• ASCII control characters (except NULL and whitespace)\n")?;
    cfg.reset(&mut out)?;
    // Non-ascii
    cfg.nonascii.apply(&mut out)?;
    write!(out, "× Non-ASCII bytes (0x80 - 0xFF)\n")?;
    cfg.reset(&mut out)?;

    out.flush().ok();
    // Suppress unused
    let _ = args;
    Ok(())
}
