            end - as_u64
        } else {
            args.skip as u64
        };
        reader.seek(SeekFrom::Start(target))
            .map_err(|_| MyError::new("Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe)."))?;
    }
    let base_offset = if args.skip < 0 {
        // Calculate actual base from end
        if let Some(len) = total_len {
            let off = args.skip;
            let as_u64 = (-off) as u64;
            len.saturating_sub(as_u64)
        } else {
            // Shouldn't happen for stdin
            0
        }
    } else {
        args.skip as u64
    };

    // Handle length limit - read bytes
    let data = read_all_bytes(&mut reader, args.length)?;
    drop(reader);

    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());

    if args.include {
        hex_dump::write_include(&mut out, &data, args.file.as_deref(), is_file)?;
