// Argument parsing
use crate::parse_num;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ColorWhen { Always, Auto, Never, Force }

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BorderStyle { Unicode, Ascii, None }

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CharTable { Default, Ascii, Codepage1047, Codepage437, Braille }

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ColorScheme { Default, Gradient }

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Endianness { Little, Big }

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Base { Binary, Octal, Decimal, Hexadecimal }

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PanelsOpt { Auto, N(u64) }

#[derive(Debug)]
pub struct Args {
    pub file: Option<String>,
    pub length: Option<u64>,
    pub skip: i64, // can be negative
    pub block_size: u64,
    pub no_squeezing: bool,
    pub color: ColorWhen,
    pub border: BorderStyle,
    pub plain: bool,
    pub no_characters: bool,
    pub character_table: CharTable,
    pub color_scheme: ColorScheme,
    pub no_position: bool,
