    pub panels: Option<PanelsOpt>,
    pub group_size: u8,
    pub endianness: Endianness,
    pub base: Base,
    pub terminal_width: Option<u64>,
    pub print_color_table: bool,
    pub include: bool,
    pub completion: Option<String>,
}

impl Default for Args {
    fn default() -> Self {
        Args {
            file: None,
            length: None,
            skip: 0,
            block_size: 512,
            no_squeezing: false,
            color: ColorWhen::Always,
            border: BorderStyle::Unicode,
            plain: false,
            no_characters: false,
            character_table: CharTable::Default,
            color_scheme: ColorScheme::Default,
            no_position: false,
            display_offset: 0,
            panels: None,
            group_size: 1,
            endianness: Endianness::Big,
            base: Base::Hexadecimal,
            terminal_width: None,
            print_color_table: false,
            include: false,
            completion: None,
        }
    }
}

pub enum ArgsError {
    Usage(String),
    Help(String),
    Version(String),
}

fn usage(msg: String) -> ArgsError {
    ArgsError::Usage(msg)
}

fn require_value<'a>(
    flag: &str,
    iter: &mut std::slice::Iter<'a, String>,
) -> Result<&'a str, ArgsError> {
    match iter.next() {
        Some(s) => Ok(s.as_str()),
        None => Err(usage(format!(
            "error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.\n",
            flag
        ))),
    }
}

// Split --key=value; returns (key, Some(value)) or (arg, None).
fn split_eq(arg: &str) -> (&str, Option<&str>) {
    if let Some(i) = arg.find('=') {
        (&arg[..i], Some(&arg[i+1..]))
    } else {
        (arg, None)
    }
}

pub fn parse_args(argv: &[String]) -> Result<Args, ArgsError> {
    let mut args = Args::default();
    let mut iter = argv[1..].iter();
    let mut saw_panels = false;
    let mut saw_terminal_width = false;
    let mut positional: Vec<String> = Vec::new();
    let mut skip_str: Option<String> = None;

    while let Some(a) = iter.next() {
        let s = a.as_str();

        if s == "--" {
            while let Some(rest) = iter.next() {
                positional.push(rest.clone());
            }
            break;
        }

        // Handle long options
        if let Some(rest) = s.strip_prefix("--") {
            let (key, val) = split_eq(rest);
            match key {
                "help" => return Err(ArgsError::Help(help_long())),
                "version" => return Err(ArgsError::Version(version_str())),
                "length" | "bytes" => {
                    let v = match val { Some(v) => v, None => require_value(&format!("--{}", key), &mut iter)? };
                    let n = parse_num::parse_byte_count(v, args.block_size).map_err(|e| {
                        usage(format!(
                            "Error: failed to parse `--length` arg \"{}\" as byte count\n\nCaused by:\n{}",
                            v, format_causes(&e)
                        ))
                    })?;
                    args.length = Some(n);
                }
                "skip" => {
                    let v = match val { Some(v) => v, None => require_value("--skip", &mut iter)? };
                    skip_str = Some(v.to_string());
                }
                "block-size" => {
                    let v = match val { Some(v) => v, None => require_value("--block-size", &mut iter)? };
                    // block-size is parsed with fixed units (doesn't use block unit itself)
                    let n = parse_num::parse_byte_count(v, 1).map_err(|e| {
                        usage(format!(
                            "Error: failed to parse `--block-size` arg \"{}\" as byte count\n\nCaused by:\n{}",
                            v, format_causes(&e)
                        ))
                    })?;
                    args.block_size = n;
                }
                "no-squeezing" => args.no_squeezing = true,
                "color" => {
                    let v = match val { Some(v) => v, None => require_value("--color", &mut iter)? };
                    args.color = match v {
                        "always" => ColorWhen::Always,
                        "auto" => ColorWhen::Auto,
                        "never" => ColorWhen::Never,
