fn format_causes(e: &parse_num::ParseError) -> String {
    match &e.sub_causes {
        Some(v) => {
            let mut out = String::new();
            for (i, c) in v.iter().enumerate() {
                out.push_str(&format!("    {}: {}\n", i, c));
            }
