                        ))
                    })?;
                    args.block_size = n;
                }
                "no-squeezing" => args.no_squeezing = true,
                "color" => {
                    let v = match val { Some(v) => v, None => require_value("--color", &mut iter)? };
                    args.color = match v {
                        "always" => ColorWhen::Always,
                        "auto" => ColorWhen::Auto,
                        "never" => ColorWhen::Never,
                        "force" => ColorWhen::Force,
                        _ => return Err(usage(format!("error: invalid value '{}' for '--color <WHEN>'\n  [possible values: always, auto, never, force]\n\nFor more information, try '--help'.\n", v))),
                    };
                }
                "border" => {
                    let v = match val { Some(v) => v, None => require_value("--border", &mut iter)? };
                    args.border = match v {
                        "unicode" => BorderStyle::Unicode,
                        "ascii" => BorderStyle::Ascii,
                        "none" => BorderStyle::None,
                        _ => return Err(usage(format!("error: invalid value '{}' for '--border <STYLE>'\n  [possible values: unicode, ascii, none]\n\nFor more information, try '--help'.\n", v))),
