                }
                "plain" => args.plain = true,
                "no-characters" => args.no_characters = true,
                "characters" => args.no_characters = false,
                "character-table" => {
                    let v = match val { Some(v) => v, None => require_value("--character-table", &mut iter)? };
                    args.character_table = match v {
                        "default" => CharTable::Default,
                        "ascii" => CharTable::Ascii,
                        "codepage-1047" => CharTable::Codepage1047,
                        "codepage-437" => CharTable::Codepage437,
                        "braille" => CharTable::Braille,
                        _ => return Err(usage(format!("error: invalid value '{}' for '--character-table <FORMAT>'\n  [possible values: default, ascii, codepage-1047, codepage-437, braille]\n\nFor more information, try '--help'.\n", v))),
                    };
                }
                "color-scheme" => {
                    let v = match val { Some(v) => v, None => require_value("--color-scheme", &mut iter)? };
                    args.color_scheme = match v {
                        "default" => ColorScheme::Default,
                        "gradient" => ColorScheme::Gradient,
                        _ => return Err(usage(format!("error: invalid value '{}' for '--color-scheme <FORMAT>'\n  [possible values: default, gradient]\n\nFor more information, try '--help'.\n", v))),
                    };
                }
                "no-position" => args.no_position = true,
                "display-offset" => {
                    let v = match val { Some(v) => v, None => require_value("--display-offset", &mut iter)? };
                    let n = parse_num::parse_byte_count(v, args.block_size).map_err(|e| {
                        usage(format!(
                            "Error: failed to parse `--display-offset` arg \"{}\" as byte count\n\nCaused by:\n{}",
                            v, format_causes(&e)
                        ))
                    })?;
                    args.display_offset = n;
                }
                "panels" => {
                    let v = match val { Some(v) => v, None => require_value("--panels", &mut iter)? };
                    saw_panels = true;
                    if v == "auto" {
                        args.panels = Some(PanelsOpt::Auto);
                    } else {
                        let n: u64 = v.parse().map_err(|_| {
                            usage(format!(
                                "Error: failed to parse `--panels` arg \"{}\" as unsigned nonzero integer\n\nCaused by:\n    invalid digit found in string\n",
                                v
                            ))
                        })?;
                        if n == 0 {
                            return Err(usage(format!(
                                "Error: failed to parse `--panels` arg \"{}\" as unsigned nonzero integer\n\nCaused by:\n    number would be zero for non-zero type\n",
                                v
                            )));
                        }
                        args.panels = Some(PanelsOpt::N(n));
                    }
                }
                "group-size" | "groupsize" => {
                    let v = match val { Some(v) => v, None => require_value("--group-size", &mut iter)? };
                    args.group_size = match v {
                        "1" => 1,
                        "2" => 2,
                        "4" => 4,
                        "8" => 8,
                        _ => return Err(usage(format!("error: invalid value '{}' for '--group-size <N>'\n  [possible values: 1, 2, 4, 8]\n\nFor more information, try '--help'.\n", v))),
                    };
                }
                "endianness" => {
                    let v = match val { Some(v) => v, None => require_value("--endianness", &mut iter)? };
                    args.endianness = match v {
                        "little" => Endianness::Little,
                        "big" => Endianness::Big,
                        _ => return Err(usage(format!("error: invalid value '{}' for '--endianness <FORMAT>'\n  [possible values: little, big]\n\nFor more information, try '--help'.\n", v))),
                    };
                }
                "base" => {
                    let v = match val { Some(v) => v, None => require_value("--base", &mut iter)? };
                    args.base = parse_base(v)?;
                }
                "terminal-width" => {
                    let v = match val { Some(v) => v, None => require_value("--terminal-width", &mut iter)? };
                    saw_terminal_width = true;
                    let n: u64 = v.parse().map_err(|_| {
                        usage(format!("error: invalid value '{}' for '--terminal-width <N>'\n\nFor more information, try '--help'.\n", v))
                    })?;
                    args.terminal_width = Some(n);
                }
                "print-color-table" => args.print_color_table = true,
                "include" => args.include = true,
                "completion" => {
                    let v = match val { Some(v) => v, None => require_value("--completion", &mut iter)? };
                    let v = match v {
                        "bash" | "elvish" | "fish" | "powershell" | "zsh" => v.to_string(),
                        _ => return Err(usage(format!("error: invalid value '{}' for '--completion <SHELL>'\n  [possible values: bash, elvish, fish, powershell, zsh]\n\nFor more information, try '--help'.\n", v))),
                    };
                    args.completion = Some(v);
                }
                _ => return Err(usage(format!("error: unexpected argument '--{}' found\n\nFor more information, try '--help'.\n", key))),
            }
            continue;
        }

        // Short options (-x), possibly combined
        if let Some(rest) = s.strip_prefix('-') {
            if rest.is_empty() {
                // "-" means stdin (treat as positional)
                positional.push(s.to_string());
                continue;
            }
            // Multiple short options in one arg
            let mut chars = rest.chars().peekable();
            while let Some(c) = chars.next() {
                match c {
                    'h' => return Err(ArgsError::Help(help_short())),
                    'V' => return Err(ArgsError::Version(version_str())),
                    'v' => { args.no_squeezing = true; }
                    'p' => { args.plain = true; }
                    'P' => { args.no_position = true; }
                    'C' => { args.no_characters = false; }
                    'i' => { args.include = true; }
                    'e' => { args.endianness = Endianness::Little; }
                    'n' | 'c' | 'l' => {
                        let v = take_short_val(c, &mut chars, &mut iter)?;
                        let n = parse_num::parse_byte_count(&v, args.block_size).map_err(|e| {
                            usage(format!(
                                "Error: failed to parse `--length` arg \"{}\" as byte count\n\nCaused by:\n{}",
                                v, format_causes(&e)
                            ))
                        })?;
                        args.length = Some(n);
                        break;
                    }
                    's' => {
                        let v = take_short_val(c, &mut chars, &mut iter)?;
                        skip_str = Some(v);
                        break;
                    }
                    'o' => {
                        let v = take_short_val(c, &mut chars, &mut iter)?;
                        let n = parse_num::parse_byte_count(&v, args.block_size).map_err(|e| {
                            usage(format!(
                                "Error: failed to parse `--display-offset` arg \"{}\" as byte count\n\nCaused by:\n{}",
                                v, format_causes(&e)
                            ))
                        })?;
                        args.display_offset = n;
                        break;
                    }
                    'g' => {
                        let v = take_short_val(c, &mut chars, &mut iter)?;
                        args.group_size = match v.as_str() {
                            "1" => 1,
                            "2" => 2,
                            "4" => 4,
                            "8" => 8,
                            _ => return Err(usage(format!("error: invalid value '{}' for '--group-size <N>'\n  [possible values: 1, 2, 4, 8]\n\nFor more information, try '--help'.\n", v))),
                        };
                        break;
                    }
                    'b' => {
                        let v = take_short_val(c, &mut chars, &mut iter)?;
                        args.base = parse_base(&v)?;
                        break;
                    }
                    _ => return Err(usage(format!("error: unexpected argument '-{}' found\n\nFor more information, try '--help'.\n", c))),
                }
            }
            continue;
        }

        // Positional
        positional.push(s.to_string());
    }

    if saw_panels && saw_terminal_width {
        return Err(usage("error: the argument '--panels <N>' cannot be used with '--terminal-width <N>'\n\nFor more information, try '--help'.\n".to_string()));
    }

    // Apply positional as FILE
    if positional.len() > 1 {
        return Err(usage(format!(
            "error: unexpected argument '{}' found\n\nFor more information, try '--help'.\n",
            positional[1]
        )));
    }
    if let Some(file) = positional.into_iter().next() {
        if file != "-" {
            args.file = Some(file);
        }
    }

    // Parse skip after args since block-size may come later
    if let Some(s) = skip_str {
        let neg = s.starts_with('-');
        let abs_val = if neg { &s[1..] } else { s.as_str() };
        if neg {
            let n = parse_num::parse_byte_count_allow_any(abs_val, args.block_size).map_err(|e| {
                usage(format!(
                    "Error: failed to parse `--skip` arg \"{}\" as byte count\n\nCaused by:\n{}",
                    s, format_causes(&e)
                ))
            })?;
            args.skip = -(n as i64);
        } else {
            let n = parse_num::parse_byte_count(abs_val, args.block_size).map_err(|e| {
                usage(format!(
                    "Error: failed to parse `--skip` arg \"{}\" as byte count\n\nCaused by:\n{}",
                    s, format_causes(&e)
                ))
            })?;
            args.skip = n as i64;
        }
    }

    // Handle --plain implications  
    if args.plain {
        args.border = BorderStyle::None;
        args.no_characters = true;
        args.no_position = true;
        args.color = ColorWhen::Never;
    }

    Ok(args)
}

fn take_short_val(
    c: char,
    chars: &mut std::iter::Peekable<std::str::Chars>,
    iter: &mut std::slice::Iter<'_, String>,
) -> Result<String, ArgsError> {
    // Remainder of current arg
    let rest: String = chars.collect();
    if !rest.is_empty() {
        let r = if let Some(stripped) = rest.strip_prefix('=') { stripped.to_string() } else { rest };
        Ok(r)
    } else {
        match iter.next() {
            Some(s) => Ok(s.clone()),
            None => Err(usage(format!(
                "error: a value is required for '-{}' but none was supplied\n\nFor more information, try '--help'.\n",
                c
            ))),
        }
    }
}

fn parse_base(v: &str) -> Result<Base, ArgsError> {
    match v {
        "b" | "binary" => Ok(Base::Binary),
        "o" | "octal" => Ok(Base::Octal),
        "d" | "decimal" => Ok(Base::Decimal),
        "x" | "hex" | "hexadecimal" => Ok(Base::Hexadecimal),
        _ => Err(usage(format!(
            "Error: The base provided is not valid. Valid bases are \"b\", \"o\", \"d\", and \"x\".\n"
        ))),
    }
}

fn format_causes(e: &parse_num::ParseError) -> String {
    match &e.sub_causes {
        Some(v) => {
            let mut out = String::new();
            for (i, c) in v.iter().enumerate() {
                out.push_str(&format!("    {}: {}\n", i, c));
            }
            out
        }
        None => format!("    {}\n", e.msg),
    }
}

pub fn version_str() -> String {
    "hexyl 0.16.0\n".to_string()
}

pub fn help_long() -> String {
    include_str!("help_long.txt").to_string()
}

pub fn help_short() -> String {
    include_str!("help_short.txt").to_string()
}
