        // just to avoid lifetime complication
        let _ = &lowered;
        (&s[2..], 16u32)
    } else {
        (s, 10u32)
    };
    u64::from_str_radix(parse_s, radix).map_err(|_| ParseError::simple("invalid digit found in string"))
