// Byte categories

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ByteCategory {
    Null,
    AsciiPrintable,
    AsciiWhitespace,
    AsciiOther,
    NonAscii,
}

pub fn categorize(b: u8) -> ByteCategory {
    if b == 0x00 {
        ByteCategory::Null
    } else if is_ascii_whitespace(b) {
        ByteCategory::AsciiWhitespace
    } else if is_ascii_printable(b) {
        ByteCategory::AsciiPrintable
    } else if b < 0x80 {
        ByteCategory::AsciiOther
    } else {
        ByteCategory::NonAscii
    }
}

// Rust's is_ascii_whitespace: 0x09 TAB, 0x0A LF, 0x0C FF, 0x0D CR, 0x20 SPACE
pub fn is_ascii_whitespace(b: u8) -> bool {
    matches!(b, 0x09 | 0x0A | 0x0C | 0x0D | 0x20)
}

pub fn is_ascii_printable(b: u8) -> bool {
    // 0x20..=0x7E (but 0x20 is whitespace, caller checks)
    (0x20..=0x7E).contains(&b)
}
