// Color handling
use std::io::{self, Write};
use std::env;
use crate::byte::ByteCategory;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Color {
    None,
    Ansi16(u8),      // 30..37, 90..97
    Rgb(u8, u8, u8),
}

impl Color {
    pub fn escape(&self) -> String {
        match self {
            Color::None => String::new(),
            Color::Ansi16(n) => format!("\x1b[{}m", n),
            Color::Rgb(r,g,b) => format!("\x1b[38;2;{:03};{:03};{:03}m", r, g, b),
        }
    }
}

// Parse env var color. Returns None if invalid.
fn parse_color(s: &str) -> Option<Color> {
    let trimmed = s.trim();
    // RGB hex
    if let Some(hex) = trimmed.strip_prefix('#') {
        if hex.len() == 6 && hex.chars().all(|c| c.is_ascii_hexdigit()) {
            let r = u8::from_str_radix(&hex[0..2], 16).ok()?;
            let g = u8::from_str_radix(&hex[2..4], 16).ok()?;
            let b = u8::from_str_radix(&hex[4..6], 16).ok()?;
            return Some(Color::Rgb(r,g,b));
        }
        return None;
    }
    // Named colors (case-insensitive)
    let low = trimmed.to_ascii_lowercase();
    let (bright, name) = if let Some(rest) = low.strip_prefix("bright ") {
        (true, rest)
    } else if let Some(rest) = low.strip_prefix("bright") {
        (true, rest.trim_start())
    } else {
        (false, low.as_str())
    };
    let base = match name.trim() {
        "black" => 0,
        "red" => 1,
        "green" => 2,
        "yellow" => 3,
        "blue" => 4,
        "magenta" | "purple" => 5,
        "cyan" => 6,
        "white" => 7,
        _ => return None,
    };
    let code = if bright { 90 + base } else { 30 + base };
    Some(Color::Ansi16(code))
}

#[derive(Clone, Debug)]
pub struct ColorConfig {
    pub active: bool,
    pub null: Color,
    pub offset: Color,
    pub printable: Color,
    pub whitespace: Color,
    pub other: Color,
    pub nonascii: Color,
}

impl ColorConfig {
    pub fn from_env(active: bool) -> Self {
        let def = Self::default();
        let null = env::var("HEXYL_COLOR_NULL").ok().and_then(|s| parse_color(&s)).unwrap_or(def.null);
        let offset = env::var("HEXYL_COLOR_OFFSET").ok().and_then(|s| parse_color(&s)).unwrap_or(def.offset);
        let printable = env::var("HEXYL_COLOR_ASCII_PRINTABLE").ok().and_then(|s| parse_color(&s)).unwrap_or(def.printable);
        let whitespace = env::var("HEXYL_COLOR_ASCII_WHITESPACE").ok().and_then(|s| parse_color(&s)).unwrap_or(def.whitespace);
        let other = env::var("HEXYL_COLOR_ASCII_OTHER").ok().and_then(|s| parse_color(&s)).unwrap_or(def.other);
        let nonascii = env::var("HEXYL_COLOR_NONASCII").ok().and_then(|s| parse_color(&s)).unwrap_or(def.nonascii);
        Self { active, null, offset, printable, whitespace, other, nonascii }
    }

    pub fn default() -> Self {
        Self {
            active: true,
            null: Color::Ansi16(90),      // bright black
            offset: Color::Ansi16(90),
            printable: Color::Ansi16(36), // cyan
            whitespace: Color::Ansi16(32), // green
            other: Color::Ansi16(32),     // green
            nonascii: Color::Ansi16(33),  // yellow
        }
    }

    pub fn color_for(&self, cat: ByteCategory) -> &Color {
        match cat {
            ByteCategory::Null => &self.null,
            ByteCategory::AsciiPrintable => &self.printable,
            ByteCategory::AsciiWhitespace => &self.whitespace,
            ByteCategory::AsciiOther => &self.other,
            ByteCategory::NonAscii => &self.nonascii,
        }
    }

    pub fn apply<W: Write>(&self, w: &mut W, color: &Color) -> io::Result<()> {
        if !self.active { return Ok(()); }
        match color {
            Color::None => (),
            _ => w.write_all(color.escape().as_bytes())?,
        }
        Ok(())
    }

    pub fn reset<W: Write>(&self, w: &mut W) -> io::Result<()> {
        if !self.active { return Ok(()); }
        w.write_all(b"\x1b[39m")?;
        Ok(())
    }
}

// Extension for Color to emit itself
pub trait ColorApply {
    fn apply<W: Write>(&self, w: &mut W) -> io::Result<()>;
}
impl ColorApply for Color {
    fn apply<W: Write>(&self, w: &mut W) -> io::Result<()> {
        w.write_all(self.escape().as_bytes())
    }
}
