pub fn write_include<W: Write>(
    out: &mut W,
    data: &[u8],
    file: Option<&str>,
    is_file: bool,
) -> io::Result<()> {
    if !is_file {
        // When reading from stdin, just output the bytes as hex, 12 per line, no header/footer
        write_c_bytes(out, data)?;
        if !data.is_empty() {
            out.write_all(b"\n")?;
        }
        return Ok(());
    }
    let name = file.map(sanitize_name).unwrap_or_else(|| "stdin".to_string());
    writeln!(out, "unsigned char {}[] = {{", name)?;
    write_c_bytes(out, data)?;
    if !data.is_empty() {
        writeln!(out)?;
    }
    writeln!(out, "}};")?;
    writeln!(out, "unsigned int {}_len = {};", name, data.len())?;
    Ok(())
}

fn write_c_bytes<W: Write>(out: &mut W, data: &[u8]) -> io::Result<()> {
    for (i, chunk) in data.chunks(12).enumerate() {
        if i > 0 { writeln!(out, ",")?; }
        out.write_all(b"  ")?;
        let strs: Vec<String> = chunk.iter().map(|b| format!("0x{:02x}", b)).collect();
        out.write_all(strs.join(", ").as_bytes())?;
    }
    Ok(())
}

fn sanitize_name(path: &str) -> String {
    // Strip directory
    let base = path.rsplit('/').next().unwrap_or(path);
    let mut s = String::new();
    let bytes = base.as_bytes();
    for (i, &b) in bytes.iter().enumerate() {
        let c = b as char;
        if i == 0 && c.is_ascii_digit() {
            s.push('_');
        }
        if c.is_ascii_alphanumeric() || c == '_' {
            s.push(c);
        } else {
            s.push('_');
        }
    }
    s
}

// Compute full-line chars (based on offset width + panels + char-panels)
#[derive(Debug, Clone, Copy)]
struct Layout {
    show_position: bool,
    show_chars: bool,
    border: BorderStyle,
    panels: u64,
    bytes_per_line: u64,
    bytes_per_panel: u64,
    hex_panel_width: usize,  // chars inside one hex panel (between separators)
    char_panel_width: usize, // chars inside one char panel
    offset_width: usize,
    base: Base,
    group_size: u8,
    endianness: Endianness,
}

fn compute_layout(args: &Args) -> Layout {
    let bytes_per_panel: u64 = 8;
    // Compute panels based on terminal width or --panels
    let default_panels: u64 = match args.base {
        Base::Hexadecimal => 2,
        _ => 1,
    };

    let panels = match (args.panels, args.terminal_width) {
        (Some(PanelsOpt::N(n)), None) => n,
        (Some(PanelsOpt::Auto), None) => {
            let tw = terminal_width().unwrap_or(80);
            let p = auto_panels(tw, args);
            p.max(1)
        }
        (None, Some(tw)) => {
            let p = auto_panels(tw, args);
            p.max(1)
        }
        (None, None) => {
            let tw = terminal_width();
            match tw {
                Some(w) => {
                    let p = auto_panels(w, args);
                    if p < default_panels { p.max(1) } else { default_panels }
                }
                None => default_panels,
            }
        }
        _ => default_panels,
    };
    // Hex width per panel depends on base and group size
    let hex_width = hex_panel_width(args.base, bytes_per_panel, args.group_size);
    let char_width = if matches!(args.character_table, CharTable::Ascii | CharTable::Codepage1047) {
        bytes_per_panel as usize
    } else {
        bytes_per_panel as usize
    };
    Layout {
        show_position: !args.no_position,
        show_chars: !args.no_characters,
        border: args.border,
        panels,
        bytes_per_line: bytes_per_panel * panels,
        bytes_per_panel,
        hex_panel_width: hex_width,
        char_panel_width: char_width,
        offset_width: 8,
        base: args.base,
        group_size: args.group_size,
        endianness: args.endianness,
    }
}

fn hex_panel_width(base: Base, bytes_per_panel: u64, group_size: u8) -> usize {
    let chars_per_byte = match base {
        Base::Binary => 8,
        Base::Octal => 3,
        Base::Decimal => 3,
        Base::Hexadecimal => 2,
    };
    let bpp = bytes_per_panel as usize;
    let gs = group_size as usize;
    // Groups of gs bytes printed together (no internal space)
    let groups = bpp / gs;
    // Each group is chars_per_byte * gs characters.
    // Then groups are separated by space.
    // Plus leading and trailing space.
    // panel format: " GROUP GROUP GROUP " for groups count
    let group_chars = chars_per_byte * gs;
    1 + groups * group_chars + (groups - 1) + 1
}

fn auto_panels(tw: u64, args: &Args) -> u64 {
    // Calculate max panels that fit in tw
    let bytes_per_panel: u64 = 8;
    let group_size = args.group_size;
    let hex_width = hex_panel_width(args.base, bytes_per_panel, group_size);
    let char_width = bytes_per_panel as usize;
    let offset_width = 8;

    let mut fixed = 0usize;
    if !args.no_position {
        fixed += 1 + offset_width + 1; // │OFFSET│
    } else {
        fixed += 1; // │
    }
    fixed += 1; // closing │

    // Per panel cost: hex_width + 1 (│ or ┊) . For first panel, we've added the divider above? Let me redo.
    // Layout: [│ OFFSET │][ hex1 ][┊ hex2 ]...[ hexN │][ char1 ┊ char2 ... charN │]
    // Let's simplify. Without position: 1 (│) + N*hex_width + (N-1) ┊ + 1 │ + (if chars) N*char + (N-1) + 1
    // With position: 1 + offset + 1 + N*hex + (N-1) + 1 + (N*char + (N-1) + 1 if chars)

    let per_panel_hex = hex_width + 1; // hex + trailing separator (┊ or │)
    let per_panel_char = char_width + 1;

    // The (N-1) of ┊ within hex panels is included as per_panel_hex (each panel's trailing) minus the last one which is │ instead of ┊. Since both are 1 char, it's fine.
    // So total = fixed_without_chars = position_section + N*per_panel_hex
    let mut base_width = fixed + 0;  // need: fixed covers │OFFSET│ + │ closing
    // Actually rewrite:
    let mut overhead: usize;
    if !args.no_position {
        overhead = 1 + offset_width + 1; // │OFFSET│
    } else {
        overhead = 1; // │
    }
    if !args.no_characters {
        overhead += 1; // trailing │ after hex panels + closing │ of chars is counted per-panel
    }
    overhead += 1; // final │
    let mut per_panel = hex_width + 1;
    if !args.no_characters {
        per_panel += char_width + 1;
    }
    // Some things are off, easier approach: just try values
    let _ = (base_width, overhead, per_panel);

    // Easier: iterate N from 1 and compute width
    let mut best = 1u64;
    for n in 1..=64u64 {
        let w = computed_width(n, args, hex_width, char_width, offset_width);
        if w <= tw {
            best = n;
        } else {
            break;
        }
    }
    best
}

fn computed_width(n: u64, args: &Args, hex_width: usize, char_width: usize, offset_width: usize) -> u64 {
    let n_us = n as usize;
    // Left: │ [OFFSET │] 
    let mut w: usize = 1;
    if !args.no_position {
        w += offset_width + 1;
    }
    // Hex panels: N panels separated by ┊ (1 each), final panel followed by │
    w += n_us * hex_width;
    w += n_us; // separators between panels + final │
    // Actually: hex1 ┊ hex2 ┊ ... ┊ hexN │ → N panels, (N-1) ┊, 1 │ → total N separators
    // OK so hex_panels + N char separators = correct

    if !args.no_characters {
        w += n_us * char_width;
        w += n_us; // (N-1) ┊ + 1 │
    }
    w as u64
}

fn terminal_width() -> Option<u64> {
    #[cfg(unix)]
    {
        use std::os::fd::AsRawFd;
        unsafe {
            let mut ws: libc_winsize = std::mem::zeroed();
            let fd = std::io::stdout().as_raw_fd();
            if ioctl_tiocgwinsz(fd, &mut ws) == 0 && ws.ws_col > 0 {
                return Some(ws.ws_col as u64);
            }
        }
    }
    None
}

#[repr(C)]
#[allow(non_camel_case_types)]
struct libc_winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn ioctl(fd: libc::c_int, request: libc::c_ulong, ...) -> libc::c_int;
}

mod libc {
    pub type c_int = i32;
    pub type c_ulong = u64;
}

#[cfg(unix)]
unsafe fn ioctl_tiocgwinsz(fd: libc::c_int, ws: *mut libc_winsize) -> libc::c_int {
    const TIOCGWINSZ: libc::c_ulong = 0x5413;
    ioctl(fd, TIOCGWINSZ, ws)
}

// Box-drawing character sets
struct BoxChars {
    // Corners
    top_left: char,
    top_right: char,
    bot_left: char,
    bot_right: char,
    // T pieces
    top_t: char,      // ┬ or +
    bot_t: char,      // ┴ or +
    // Line chars
    horiz: char,      // ─ or -
    vert: char,       // │ or |
    inner_sep: char,  // ┊ or | or ' '
    outer_vert: char, // │ or | or ' '
}

fn boxchars(border: BorderStyle) -> BoxChars {
    match border {
        BorderStyle::Unicode => BoxChars {
            top_left: '┌', top_right: '┐', bot_left: '└', bot_right: '┘',
            top_t: '┬', bot_t: '┴',
            horiz: '─', vert: '│',
            inner_sep: '┊', outer_vert: '│',
        },
        BorderStyle::Ascii => BoxChars {
            top_left: '+', top_right: '+', bot_left: '+', bot_right: '+',
            top_t: '+', bot_t: '+',
            horiz: '-', vert: '|',
            inner_sep: '|', outer_vert: '|',
        },
        BorderStyle::None => BoxChars {
            top_left: ' ', top_right: ' ', bot_left: ' ', bot_right: ' ',
            top_t: ' ', bot_t: ' ',
            horiz: ' ', vert: ' ',
            inner_sep: ' ', outer_vert: ' ',
        },
    }
}

pub fn write_dump<W: Write>(
    out: &mut W,
    data: &[u8],
    base_offset: u64,
    args: &Args,
    cfg: &ColorConfig,
) -> io::Result<()> {
    let layout = compute_layout(args);
    let bc = boxchars(layout.border);
    let show_border = !matches!(layout.border, BorderStyle::None);

    // Handle "No content" for empty input
    if data.is_empty() {
        write_no_content(out, args, &layout)?;
        return Ok(());
    }

    // Top border
    if show_border {
        write_horizontal_border(out, &layout, &bc, bc.top_left, bc.top_right, bc.top_t)?;
    }

    // Iterate lines
    let bpl = layout.bytes_per_line as usize;
    let mut offset = base_offset.saturating_add(args.display_offset);
    let mut prev_line: Option<&[u8]> = None;
    let mut squeezed = false; // are we in a squeeze state
    let mut i = 0usize;
    while i < data.len() {
        let end = (i + bpl).min(data.len());
        let line = &data[i..end];
        let is_full = line.len() == bpl;

        // Squeeze check
        if !args.no_squeezing {
            if let Some(p) = prev_line {
                if p == line && is_full {
                    if !squeezed {
                        write_squeeze_row(out, &layout, &bc, cfg)?;
                        squeezed = true;
                    }
                    offset += bpl as u64;
                    i += bpl;
                    continue;
                } else {
                    squeezed = false;
                }
            }
        }

        write_data_row(out, offset, line, &layout, &bc, cfg, args)?;
        prev_line = Some(line);
        offset = offset.saturating_add(bpl as u64);
        i += bpl;
    }

    // End row: always shows next offset on its own line (if there's more or squeeze state)
    if squeezed && show_border {
        // After squeeze, we need to show the current offset (empty row showing offset)
        write_empty_offset_row(out, offset, &layout, &bc, cfg, args)?;
    } else if squeezed {
        write_empty_offset_row(out, offset, &layout, &bc, cfg, args)?;
    }

    // Bottom border
    if show_border {
        write_horizontal_border(out, &layout, &bc, bc.bot_left, bc.bot_right, bc.bot_t)?;
    }

    Ok(())
}

fn write_no_content<W: Write>(out: &mut W, args: &Args, layout: &Layout) -> io::Result<()> {
    // Always uses unicode chars per observation
    let bc = boxchars(BorderStyle::Unicode);
    let show_border = !matches!(layout.border, BorderStyle::None);
    let topbc = if matches!(layout.border, BorderStyle::Ascii) { boxchars(BorderStyle::Ascii) } else { bc };
    // Top
    if show_border {
        write_horizontal_border(out, layout, &topbc, topbc.top_left, topbc.top_right, topbc.top_t)?;
    }

    // Content line: │        │ No content              │                         │        │        │
    let _ = args;
    // Emit: │ (offset_width spaces) │ " No content" + pad │ ...
    if layout.show_position {
        out.write_all(bc.outer_vert.to_string().as_bytes())?;
        for _ in 0..layout.offset_width { out.write_all(b" ")?; }
    } else {
        out.write_all(bc.outer_vert.to_string().as_bytes())?;
    }
    out.write_all(bc.vert.to_string().as_bytes())?;
    // First hex panel: " No content" padded to hex_panel_width
    let nc = " No content";
    out.write_all(nc.as_bytes())?;
    let pad = layout.hex_panel_width - nc.chars().count();
    for _ in 0..pad { out.write_all(b" ")?; }
    // Rest of hex panels
    for _ in 1..layout.panels {
        out.write_all(bc.inner_sep.to_string().as_bytes())?;
        for _ in 0..layout.hex_panel_width { out.write_all(b" ")?; }
    }
    out.write_all(bc.vert.to_string().as_bytes())?;

    if layout.show_chars {
        for i in 0..layout.panels {
            if i > 0 {
                out.write_all(bc.inner_sep.to_string().as_bytes())?;
            }
            for _ in 0..layout.char_panel_width { out.write_all(b" ")?; }
        }
        out.write_all(bc.outer_vert.to_string().as_bytes())?;
    }
    out.write_all(b"\n")?;

    if show_border {
        write_horizontal_border(out, layout, &topbc, topbc.bot_left, topbc.bot_right, topbc.bot_t)?;
    }
    Ok(())
}

fn write_horizontal_border<W: Write>(
    out: &mut W,
    layout: &Layout,
    bc: &BoxChars,
    left: char,
    right: char,
    t: char,
) -> io::Result<()> {
    out.write_all(left.to_string().as_bytes())?;
    if layout.show_position {
        for _ in 0..layout.offset_width { out.write_all(bc.horiz.to_string().as_bytes())?; }
        out.write_all(t.to_string().as_bytes())?;
    }
    for i in 0..layout.panels {
        for _ in 0..layout.hex_panel_width { out.write_all(bc.horiz.to_string().as_bytes())?; }
        if i + 1 < layout.panels {
            out.write_all(t.to_string().as_bytes())?;
        }
    }
    if layout.show_chars {
        out.write_all(t.to_string().as_bytes())?;
        for i in 0..layout.panels {
            for _ in 0..layout.char_panel_width { out.write_all(bc.horiz.to_string().as_bytes())?; }
            if i + 1 < layout.panels {
                out.write_all(t.to_string().as_bytes())?;
            }
        }
    }
    out.write_all(right.to_string().as_bytes())?;
    out.write_all(b"\n")?;
    Ok(())
}

fn write_squeeze_row<W: Write>(
    out: &mut W,
    layout: &Layout,
    bc: &BoxChars,
    _cfg: &ColorConfig,
) -> io::Result<()> {
    out.write_all(bc.outer_vert.to_string().as_bytes())?;
    if layout.show_position {
        out.write_all(b"*")?;
        for _ in 1..layout.offset_width { out.write_all(b" ")?; }
        out.write_all(bc.vert.to_string().as_bytes())?;
    }
    for i in 0..layout.panels {
        if i == 0 {
            // leading space
        } else {
            // Inner separator
            out.write_all(bc.inner_sep.to_string().as_bytes())?;
        }
        for _ in 0..layout.hex_panel_width { out.write_all(b" ")?; }
    }
    out.write_all(bc.vert.to_string().as_bytes())?;
    if layout.show_chars {
        for i in 0..layout.panels {
            if i > 0 {
                out.write_all(bc.inner_sep.to_string().as_bytes())?;
            }
            for _ in 0..layout.char_panel_width { out.write_all(b" ")?; }
        }
        out.write_all(bc.outer_vert.to_string().as_bytes())?;
    }
    out.write_all(b"\n")?;
    Ok(())
}

fn write_empty_offset_row<W: Write>(
    out: &mut W,
    offset: u64,
    layout: &Layout,
    bc: &BoxChars,
    cfg: &ColorConfig,
    _args: &Args,
) -> io::Result<()> {
    out.write_all(bc.outer_vert.to_string().as_bytes())?;
    if layout.show_position {
        if cfg.active {
            out.write_all(cfg.offset.escape().as_bytes())?;
        }
        write!(out, "{:08x}", offset)?;
        if cfg.active {
            out.write_all(b"\x1b[39m")?;
        }
        out.write_all(bc.vert.to_string().as_bytes())?;
    }
    for i in 0..layout.panels {
        if i > 0 {
            out.write_all(bc.inner_sep.to_string().as_bytes())?;
        }
        for _ in 0..layout.hex_panel_width { out.write_all(b" ")?; }
    }
    out.write_all(bc.vert.to_string().as_bytes())?;
    if layout.show_chars {
        for i in 0..layout.panels {
            if i > 0 {
                out.write_all(bc.inner_sep.to_string().as_bytes())?;
            }
            for _ in 0..layout.char_panel_width { out.write_all(b" ")?; }
        }
        out.write_all(bc.outer_vert.to_string().as_bytes())?;
    }
    out.write_all(b"\n")?;
    Ok(())
}

fn write_data_row<W: Write>(
    out: &mut W,
    offset: u64,
    line: &[u8],
    layout: &Layout,
    bc: &BoxChars,
    cfg: &ColorConfig,
    args: &Args,
) -> io::Result<()> {
    // Emit position
    out.write_all(bc.outer_vert.to_string().as_bytes())?;
    if layout.show_position {
        if cfg.active {
            out.write_all(cfg.offset.escape().as_bytes())?;
        }
        write!(out, "{:08x}", offset)?;
        if cfg.active {
            out.write_all(b"\x1b[39m")?;
        }
        out.write_all(bc.vert.to_string().as_bytes())?;
    }

    // Hex panels
    for p in 0..layout.panels {
        let panel_start = (p * layout.bytes_per_panel) as usize;
        let panel_end = (panel_start + layout.bytes_per_panel as usize).min(line.len());
        let panel_bytes: &[u8] = if panel_start < line.len() { &line[panel_start..panel_end] } else { &[] };
        write_hex_panel(out, panel_bytes, layout, cfg, args)?;
        if p + 1 < layout.panels {
            out.write_all(bc.inner_sep.to_string().as_bytes())?;
        }
    }
    out.write_all(bc.vert.to_string().as_bytes())?;

    // Char panels
    if layout.show_chars {
        for p in 0..layout.panels {
            let panel_start = (p * layout.bytes_per_panel) as usize;
            let panel_end = (panel_start + layout.bytes_per_panel as usize).min(line.len());
            let panel_bytes: &[u8] = if panel_start < line.len() { &line[panel_start..panel_end] } else { &[] };
            write_char_panel(out, panel_bytes, layout, cfg, args)?;
            if p + 1 < layout.panels {
                out.write_all(bc.inner_sep.to_string().as_bytes())?;
            }
        }
        out.write_all(bc.outer_vert.to_string().as_bytes())?;
    }
    out.write_all(b"\n")?;
    Ok(())
}

fn byte_to_str(b: u8, base: Base) -> String {
    match base {
        Base::Binary => format!("{:08b}", b),
        Base::Octal => format!("{:03o}", b),
        Base::Decimal => format!("{:03}", b),  // NOTE: below we verify
        Base::Hexadecimal => format!("{:02x}", b),
    }
}

fn chars_per_byte(base: Base) -> usize {
    match base {
        Base::Binary => 8,
        Base::Octal => 3,
        Base::Decimal => 3,
        Base::Hexadecimal => 2,
    }
}

fn write_hex_panel<W: Write>(
    out: &mut W,
    bytes: &[u8],
    layout: &Layout,
    cfg: &ColorConfig,
    args: &Args,
) -> io::Result<()> {
    // leading space (no color)
    out.write_all(b" ")?;
    let group_size = layout.group_size as usize;
    let bytes_per_panel = layout.bytes_per_panel as usize;
    let groups = bytes_per_panel / group_size;
    let cpb = chars_per_byte(layout.base);

    // We iterate groups, each group represents group_size bytes
    let mut last_color: Option<Color> = None;
    let mut color_active = false;
    for gi in 0..groups {
        if gi > 0 {
            // Separator space (inside current color if any)
            out.write_all(b" ")?;
        }
        let byte_slots = (0..group_size).map(|i| gi * group_size + i).collect::<Vec<_>>();
        // Order bytes based on endianness (little means reversed)
        let ordered: Vec<usize> = if layout.endianness == Endianness::Little {
            byte_slots.into_iter().rev().collect()
        } else {
            byte_slots
        };
        for slot in ordered {
            if slot < bytes.len() {
                let b = bytes[slot];
                let cat = categorize(b);
                let color = color_for_byte(b, cat, args, cfg);
                if cfg.active {
                    if Some(&color) != last_color.as_ref() {
                        if color_active {
                            // Actually we don't reset between bytes, just switch.
                        }
                        out.write_all(color.escape().as_bytes())?;
                        last_color = Some(color);
                        color_active = true;
                    }
                }
                let s = byte_to_str(b, layout.base);
                out.write_all(s.as_bytes())?;
            } else {
                // Missing byte - spaces same width
                for _ in 0..cpb { out.write_all(b" ")?; }
            }
        }
    }

    // Reset color
    if cfg.active && color_active {
        out.write_all(b"\x1b[39m")?;
    }
    // Trailing space (outside color)
    out.write_all(b" ")?;
    Ok(())
}

fn color_for_byte(b: u8, cat: ByteCategory, args: &Args, cfg: &ColorConfig) -> Color {
    if !cfg.active {
        return Color::None;
    }
    match args.color_scheme {
        ColorScheme::Default => cfg.color_for(cat).clone(),
        ColorScheme::Gradient => gradient_color(b, cat, cfg),
    }
}

fn gradient_color(b: u8, cat: ByteCategory, cfg: &ColorConfig) -> Color {
    // Observed pattern:
    // 0x00: gray(100,100,100)
    // 0x01..0x1F and 0x7F: pink to violet (magenta to dark violet)
    //   Observed 0x01=(255,0,255) to 0x07=(230,0,255) etc -> linear
    // 0x09..0x0D (whitespace): green 32 [?]  - Actually we saw [32m used in gradient
    // 0x20..0x7E: blue gradient
    // 0x80..0xFF: red/yellow/white gradient
    match cat {
        ByteCategory::Null => cfg.null.clone(),
        ByteCategory::AsciiWhitespace => cfg.whitespace.clone(),
        _ => {
            // Gradient
            match b {
                // Printable: from (0,128,255) at 0x20 to (0,255,0) at 0x7E
                // Non-ASCII 0x80..0xFF: red-yellow-white
                // Control: from (255,0,255) at 0x01 to (100,0,255) at 0x1F
                0x01..=0x1F | 0x7F => {
                    // Map byte -> pink-to-violet
                    // Observed: 0x01=(255,0,255) 0x02=(250,0,255) 0x03=(246,0,255) 0x04=(242,0,255) 0x05=(238,0,255) ...
                    // Interpolation across 126 values? Actually observed 0x01-0x1F and 0x7F
                    // Better: compute linear from 0x01 -> 0x7F (127 values)
                    // 0x01: (255,0,255), at 0x7F: something darker
                    // From data: 0x1F=(132,0,255). So interval (255 - X)/0x1F steps - let's see 0x01-0x1F = 30 values interval.
                    // 0x01->255, 0x1F->132: diff 123 across 30 steps. 4.1 per step.
                    // Full range 0x01 to 0x7F = 126 values. 0x7F endpoint not seen.
                    // Let me use formula: r = 255 - (b-1)*155/126 approximately
                    let idx = b as i32;
                    let r = interpolate(idx, 1, 0x7F, 255, 100);
                    let g = 0u8;
                    let bc = 255u8;
                    Color::Rgb(r, g, bc)
                }
                0x20..=0x7E => {
                    // Blue
                    // 0x20=(0,128,255), 0x2F=(0,148,234), 0x3F=(0,169,213) ...
                    // Let's fit linear from 0x20->0x7E (94 values)
                    // At 0x20: (0,128,255), at 0x7E: about (0, 255, 100)?
                    // Simple approx: g increases, b decreases
                    let idx = b as i32;
                    let g = interpolate(idx, 0x20, 0x7E, 128, 255);
                    let bc = interpolate(idx, 0x20, 0x7E, 255, 100);
                    Color::Rgb(0, g, bc)
                }
                _ => {
                    // 0x80..0xFF: red-yellow-white
                    let idx = b as i32;
                    let r = 255u8;
                    let g = interpolate(idx, 0x80, 0xFF, 0, 255);
                    let bc = interpolate(idx, 0x80, 0xFF, 0, 255);
                    Color::Rgb(r, g, bc)
                }
            }
        }
    }
}

fn interpolate(x: i32, x0: i32, x1: i32, y0: i32, y1: i32) -> u8 {
    if x1 == x0 {
        return y0.clamp(0, 255) as u8;
    }
    let y = y0 + (y1 - y0) * (x - x0) / (x1 - x0);
    y.clamp(0, 255) as u8
}

fn write_char_panel<W: Write>(
    out: &mut W,
    bytes: &[u8],
    layout: &Layout,
    cfg: &ColorConfig,
    args: &Args,
) -> io::Result<()> {
    let width = layout.char_panel_width;
    let mut last_color: Option<Color> = None;
    let mut color_active = false;
    for i in 0..width {
        if i < bytes.len() {
            let b = bytes[i];
            let cat = categorize(b);
            let color = color_for_byte(b, cat, args, cfg);
            if cfg.active {
                if Some(&color) != last_color.as_ref() {
                    out.write_all(color.escape().as_bytes())?;
                    last_color = Some(color);
                    color_active = true;
                }
            }
            let ch = byte_to_display_char(b, args.character_table);
            // Always output one char
            let mut buf = [0u8; 4];
            let s = ch.encode_utf8(&mut buf);
            out.write_all(s.as_bytes())?;
        } else {
            out.write_all(b" ")?;
        }
    }
    if cfg.active && color_active {
        out.write_all(b"\x1b[39m")?;
    }
    Ok(())
}

fn byte_to_display_char(b: u8, table: CharTable) -> char {
    match table {
        CharTable::Default => match b {
            0x00 => '\u{22C4}',  // ⋄
            0x20 => ' ',
            0x09 | 0x0A | 0x0C | 0x0D => '_',
            0x21..=0x7E => b as char,
            0x80..=0xFF => '×',
            _ => '•',
        },
        CharTable::Ascii => match b {
            0x20 => ' ',
            0x21..=0x7E => b as char,
            _ => '.',
        },
        CharTable::Codepage437 => cp437::char_for(b),
        CharTable::Codepage1047 => cp1047::char_for(b),
        CharTable::Braille => match b {
            0x00 => '\u{22C4}',
            0x09 => '\u{2192}',  // →
            0x0A => '\u{21B5}',  // ↵
            0x0D => '\u{2190}',  // ←
            0x20..=0x7E => b as char,
            _ => {
                let bits = braille_bit_remap(b);
                char::from_u32(0x2800 + bits as u32).unwrap_or('.')
            }
        }
    }
}

fn braille_bit_remap(b: u8) -> u8 {
    // byte bits -> braille bits:
    // 0->0, 1->3, 2->1, 3->4, 4->2, 5->5, 6->6, 7->7
    (b & 0x01)
        | ((b & 0x02) << 2)
        | ((b & 0x04) >> 1)
        | ((b & 0x08) << 1)
        | ((b & 0x10) >> 2)
        | (b & 0x20)
        | (b & 0x40)
        | (b & 0x80)
}
