// Hex dump rendering
use std::io::{self, Write};
use crate::args::{Args, Base, BorderStyle, CharTable, ColorScheme, Endianness, PanelsOpt};
use crate::byte::{categorize, ByteCategory};
use crate::color::{Color, ColorConfig};
