}

mod libc {
    pub type c_int = i32;
    pub type c_ulong = u64;
}

#[cfg(unix)]
unsafe fn ioctl_tiocgwinsz(fd: libc::c_int, ws: *mut libc_winsize) -> libc::c_int {
