// Box-drawing character sets
struct BoxChars {
    // Corners
    top_left: char,
    top_right: char,
    bot_left: char,
    bot_right: char,
    // T pieces
    top_t: char,      // ┬ or +
    bot_t: char,      // ┴ or +
    // Line chars
    horiz: char,      // ─ or -
    vert: char,       // │ or |
    inner_sep: char,  // ┊ or | or ' '
    outer_vert: char, // │ or | or ' '
}

fn boxchars(border: BorderStyle) -> BoxChars {
    match border {
        BorderStyle::Unicode => BoxChars {
            top_left: '┌', top_right: '┐', bot_left: '└', bot_right: '┘',
            top_t: '┬', bot_t: '┴',
            horiz: '─', vert: '│',
            inner_sep: '┊', outer_vert: '│',
        },
        BorderStyle::Ascii => BoxChars {
            top_left: '+', top_right: '+', bot_left: '+', bot_right: '+',
            top_t: '+', bot_t: '+',
            horiz: '-', vert: '|',
            inner_sep: '|', outer_vert: '|',
        },
        BorderStyle::None => BoxChars {
            top_left: ' ', top_right: ' ', bot_left: ' ', bot_right: ' ',
            top_t: ' ', bot_t: ' ',
            horiz: ' ', vert: ' ',
            inner_sep: ' ', outer_vert: ' ',
        },
    }
}

pub fn write_dump<W: Write>(
    out: &mut W,
    data: &[u8],
    base_offset: u64,
    args: &Args,
    cfg: &ColorConfig,
) -> io::Result<()> {
    let layout = compute_layout(args);
    let bc = boxchars(layout.border);
    let show_border = !matches!(layout.border, BorderStyle::None);

    // Handle "No content" for empty input
    if data.is_empty() {
        write_no_content(out, args, &layout)?;
        return Ok(());
    }

    // Top border
    if show_border {
        write_horizontal_border(out, &layout, &bc, bc.top_left, bc.top_right, bc.top_t)?;
    }

    // Iterate lines
    let bpl = layout.bytes_per_line as usize;
    let mut offset = base_offset.saturating_add(args.display_offset);
    let mut prev_line: Option<&[u8]> = None;
    let mut squeezed = false; // are we in a squeeze state
    let mut i = 0usize;
    while i < data.len() {
        let end = (i + bpl).min(data.len());
        let line = &data[i..end];
        let is_full = line.len() == bpl;

        // Squeeze check
        if !args.no_squeezing {
            if let Some(p) = prev_line {
                if p == line && is_full {
                    if !squeezed {
                        write_squeeze_row(out, &layout, &bc, cfg)?;
                        squeezed = true;
                    }
                    offset += bpl as u64;
                    i += bpl;
                    continue;
                } else {
                    squeezed = false;
                }
            }
        }

        write_data_row(out, offset, line, &layout, &bc, cfg, args)?;
        prev_line = Some(line);
        offset = offset.saturating_add(bpl as u64);
        i += bpl;
    }

    // End row: always shows next offset on its own line (if there's more or squeeze state)
    if squeezed && show_border {
        // After squeeze, we need to show the current offset (empty row showing offset)
        write_empty_offset_row(out, offset, &layout, &bc, cfg, args)?;
    } else if squeezed {
        write_empty_offset_row(out, offset, &layout, &bc, cfg, args)?;
    }

    // Bottom border
    if show_border {
        write_horizontal_border(out, &layout, &bc, bc.bot_left, bc.bot_right, bc.bot_t)?;
    }

    Ok(())
}

fn write_no_content<W: Write>(out: &mut W, args: &Args, layout: &Layout) -> io::Result<()> {
    // Always uses unicode chars per observation
    let bc = boxchars(BorderStyle::Unicode);
    let show_border = !matches!(layout.border, BorderStyle::None);
    let topbc = if matches!(layout.border, BorderStyle::Ascii) { boxchars(BorderStyle::Ascii) } else { bc };
    // Top
    if show_border {
        write_horizontal_border(out, layout, &topbc, topbc.top_left, topbc.top_right, topbc.top_t)?;
    }

    // Content line: │        │ No content              │                         │        │        │
    let _ = args;
    // Emit: │ (offset_width spaces) │ " No content" + pad │ ...
    if layout.show_position {
        out.write_all(bc.outer_vert.to_string().as_bytes())?;
        for _ in 0..layout.offset_width { out.write_all(b" ")?; }
    } else {
        out.write_all(bc.outer_vert.to_string().as_bytes())?;
    }
    out.write_all(bc.vert.to_string().as_bytes())?;
    // First hex panel: " No content" padded to hex_panel_width
    let nc = " No content";
    out.write_all(nc.as_bytes())?;
    let pad = layout.hex_panel_width - nc.chars().count();
    for _ in 0..pad { out.write_all(b" ")?; }
    // Rest of hex panels
    for _ in 1..layout.panels {
        out.write_all(bc.inner_sep.to_string().as_bytes())?;
        for _ in 0..layout.hex_panel_width { out.write_all(b" ")?; }
    }
    out.write_all(bc.vert.to_string().as_bytes())?;

    if layout.show_chars {
        for i in 0..layout.panels {
            if i > 0 {
                out.write_all(bc.inner_sep.to_string().as_bytes())?;
            }
            for _ in 0..layout.char_panel_width { out.write_all(b" ")?; }
        }
        out.write_all(bc.outer_vert.to_string().as_bytes())?;
    }
    out.write_all(b"\n")?;

    if show_border {
        write_horizontal_border(out, layout, &topbc, topbc.bot_left, topbc.bot_right, topbc.bot_t)?;
    }
    Ok(())
}

fn write_horizontal_border<W: Write>(
    out: &mut W,
    layout: &Layout,
    bc: &BoxChars,
    left: char,
    right: char,
    t: char,
) -> io::Result<()> {
    out.write_all(left.to_string().as_bytes())?;
    if layout.show_position {
        for _ in 0..layout.offset_width { out.write_all(bc.horiz.to_string().as_bytes())?; }
        out.write_all(t.to_string().as_bytes())?;
    }
    for i in 0..layout.panels {
        for _ in 0..layout.hex_panel_width { out.write_all(bc.horiz.to_string().as_bytes())?; }
        if i + 1 < layout.panels {
            out.write_all(t.to_string().as_bytes())?;
        }
    }
    if layout.show_chars {
        out.write_all(t.to_string().as_bytes())?;
        for i in 0..layout.panels {
            for _ in 0..layout.char_panel_width { out.write_all(bc.horiz.to_string().as_bytes())?; }
            if i + 1 < layout.panels {
                out.write_all(t.to_string().as_bytes())?;
            }
        }
    }
    out.write_all(right.to_string().as_bytes())?;
    out.write_all(b"\n")?;
    Ok(())
}

fn write_squeeze_row<W: Write>(
    out: &mut W,
    layout: &Layout,
    bc: &BoxChars,
    _cfg: &ColorConfig,
) -> io::Result<()> {
    out.write_all(bc.outer_vert.to_string().as_bytes())?;
    if layout.show_position {
        out.write_all(b"*")?;
        for _ in 1..layout.offset_width { out.write_all(b" ")?; }
        out.write_all(bc.vert.to_string().as_bytes())?;
    }
    for i in 0..layout.panels {
        if i == 0 {
            // leading space
        } else {
            // Inner separator
            out.write_all(bc.inner_sep.to_string().as_bytes())?;
        }
        for _ in 0..layout.hex_panel_width { out.write_all(b" ")?; }
    }
    out.write_all(bc.vert.to_string().as_bytes())?;
    if layout.show_chars {
        for i in 0..layout.panels {
            if i > 0 {
                out.write_all(bc.inner_sep.to_string().as_bytes())?;
            }
            for _ in 0..layout.char_panel_width { out.write_all(b" ")?; }
        }
        out.write_all(bc.outer_vert.to_string().as_bytes())?;
    }
    out.write_all(b"\n")?;
    Ok(())
}

fn write_empty_offset_row<W: Write>(
    out: &mut W,
    offset: u64,
    layout: &Layout,
    bc: &BoxChars,
    cfg: &ColorConfig,
    _args: &Args,
) -> io::Result<()> {
    out.write_all(bc.outer_vert.to_string().as_bytes())?;
    if layout.show_position {
        if cfg.active {
            out.write_all(cfg.offset.escape().as_bytes())?;
        }
        write!(out, "{:08x}", offset)?;
        if cfg.active {
            out.write_all(b"\x1b[39m")?;
        }
        out.write_all(bc.vert.to_string().as_bytes())?;
    }
    for i in 0..layout.panels {
        if i > 0 {
            out.write_all(bc.inner_sep.to_string().as_bytes())?;
        }
        for _ in 0..layout.hex_panel_width { out.write_all(b" ")?; }
    }
    out.write_all(bc.vert.to_string().as_bytes())?;
    if layout.show_chars {
        for i in 0..layout.panels {
            if i > 0 {
                out.write_all(bc.inner_sep.to_string().as_bytes())?;
            }
            for _ in 0..layout.char_panel_width { out.write_all(b" ")?; }
        }
        out.write_all(bc.outer_vert.to_string().as_bytes())?;
    }
    out.write_all(b"\n")?;
    Ok(())
}

fn write_data_row<W: Write>(
    out: &mut W,
    offset: u64,
    line: &[u8],
    layout: &Layout,
    bc: &BoxChars,
    cfg: &ColorConfig,
    args: &Args,
) -> io::Result<()> {
    // Emit position
    out.write_all(bc.outer_vert.to_string().as_bytes())?;
    if layout.show_position {
        if cfg.active {
            out.write_all(cfg.offset.escape().as_bytes())?;
        }
        write!(out, "{:08x}", offset)?;
        if cfg.active {
            out.write_all(b"\x1b[39m")?;
        }
        out.write_all(bc.vert.to_string().as_bytes())?;
    }

    // Hex panels
    for p in 0..layout.panels {
        let panel_start = (p * layout.bytes_per_panel) as usize;
        let panel_end = (panel_start + layout.bytes_per_panel as usize).min(line.len());
        let panel_bytes: &[u8] = if panel_start < line.len() { &line[panel_start..panel_end] } else { &[] };
        write_hex_panel(out, panel_bytes, layout, cfg, args)?;
        if p + 1 < layout.panels {
            out.write_all(bc.inner_sep.to_string().as_bytes())?;
        }
    }
    out.write_all(bc.vert.to_string().as_bytes())?;

    // Char panels
    if layout.show_chars {
        for p in 0..layout.panels {
            let panel_start = (p * layout.bytes_per_panel) as usize;
            let panel_end = (panel_start + layout.bytes_per_panel as usize).min(line.len());
            let panel_bytes: &[u8] = if panel_start < line.len() { &line[panel_start..panel_end] } else { &[] };
            write_char_panel(out, panel_bytes, layout, cfg, args)?;
            if p + 1 < layout.panels {
                out.write_all(bc.inner_sep.to_string().as_bytes())?;
            }
        }
        out.write_all(bc.outer_vert.to_string().as_bytes())?;
    }
    out.write_all(b"\n")?;
    Ok(())
}

fn byte_to_str(b: u8, base: Base) -> String {
    match base {
        Base::Binary => format!("{:08b}", b),
        Base::Octal => format!("{:03o}", b),
        Base::Decimal => format!("{:03}", b),  // NOTE: below we verify
        Base::Hexadecimal => format!("{:02x}", b),
    }
}

fn chars_per_byte(base: Base) -> usize {
    match base {
        Base::Binary => 8,
        Base::Octal => 3,
        Base::Decimal => 3,
        Base::Hexadecimal => 2,
    }
}

fn write_hex_panel<W: Write>(
    out: &mut W,
    bytes: &[u8],
    layout: &Layout,
    cfg: &ColorConfig,
    args: &Args,
) -> io::Result<()> {
    // leading space (no color)
    out.write_all(b" ")?;
    let group_size = layout.group_size as usize;
    let bytes_per_panel = layout.bytes_per_panel as usize;
    let groups = bytes_per_panel / group_size;
    let cpb = chars_per_byte(layout.base);

    // We iterate groups, each group represents group_size bytes
    let mut last_color: Option<Color> = None;
    let mut color_active = false;
    for gi in 0..groups {
        if gi > 0 {
            // Separator space (inside current color if any)
            out.write_all(b" ")?;
        }
        let byte_slots = (0..group_size).map(|i| gi * group_size + i).collect::<Vec<_>>();
        // Order bytes based on endianness (little means reversed)
        let ordered: Vec<usize> = if layout.endianness == Endianness::Little {
            byte_slots.into_iter().rev().collect()
        } else {
            byte_slots
        };
        for slot in ordered {
            if slot < bytes.len() {
                let b = bytes[slot];
                let cat = categorize(b);
                let color = color_for_byte(b, cat, args, cfg);
                if cfg.active {
                    if Some(&color) != last_color.as_ref() {
                        if color_active {
                            // Actually we don't reset between bytes, just switch.
                        }
                        out.write_all(color.escape().as_bytes())?;
                        last_color = Some(color);
                        color_active = true;
                    }
                }
                let s = byte_to_str(b, layout.base);
                out.write_all(s.as_bytes())?;
            } else {
                // Missing byte - spaces same width
                for _ in 0..cpb { out.write_all(b" ")?; }
            }
        }
    }

    // Reset color
    if cfg.active && color_active {
        out.write_all(b"\x1b[39m")?;
    }
    // Trailing space (outside color)
    out.write_all(b" ")?;
    Ok(())
}

fn color_for_byte(b: u8, cat: ByteCategory, args: &Args, cfg: &ColorConfig) -> Color {
    if !cfg.active {
        return Color::None;
    }
    match args.color_scheme {
        ColorScheme::Default => cfg.color_for(cat).clone(),
        ColorScheme::Gradient => gradient_color(b, cat, cfg),
    }
}

fn gradient_color(b: u8, cat: ByteCategory, cfg: &ColorConfig) -> Color {
    // Observed pattern:
    // 0x00: gray(100,100,100)
    // 0x01..0x1F and 0x7F: pink to violet (magenta to dark violet)
    //   Observed 0x01=(255,0,255) to 0x07=(230,0,255) etc -> linear
    // 0x09..0x0D (whitespace): green 32 [?]  - Actually we saw [32m used in gradient
    // 0x20..0x7E: blue gradient
    // 0x80..0xFF: red/yellow/white gradient
    match cat {
        ByteCategory::Null => cfg.null.clone(),
        ByteCategory::AsciiWhitespace => cfg.whitespace.clone(),
        _ => {
            // Gradient
            match b {
                // Printable: from (0,128,255) at 0x20 to (0,255,0) at 0x7E
                // Non-ASCII 0x80..0xFF: red-yellow-white
                // Control: from (255,0,255) at 0x01 to (100,0,255) at 0x1F
                0x01..=0x1F | 0x7F => {
                    // Map byte -> pink-to-violet
                    // Observed: 0x01=(255,0,255) 0x02=(250,0,255) 0x03=(246,0,255) 0x04=(242,0,255) 0x05=(238,0,255) ...
                    // Interpolation across 126 values? Actually observed 0x01-0x1F and 0x7F
                    // Better: compute linear from 0x01 -> 0x7F (127 values)
                    // 0x01: (255,0,255), at 0x7F: something darker
                    // From data: 0x1F=(132,0,255). So interval (255 - X)/0x1F steps - let's see 0x01-0x1F = 30 values interval.
                    // 0x01->255, 0x1F->132: diff 123 across 30 steps. 4.1 per step.
                    // Full range 0x01 to 0x7F = 126 values. 0x7F endpoint not seen.
                    // Let me use formula: r = 255 - (b-1)*155/126 approximately
                    let idx = b as i32;
                    let r = interpolate(idx, 1, 0x7F, 255, 100);
                    let g = 0u8;
                    let bc = 255u8;
                    Color::Rgb(r, g, bc)
                }
                0x20..=0x7E => {
                    // Blue
                    // 0x20=(0,128,255), 0x2F=(0,148,234), 0x3F=(0,169,213) ...
                    // Let's fit linear from 0x20->0x7E (94 values)
                    // At 0x20: (0,128,255), at 0x7E: about (0, 255, 100)?
                    // Simple approx: g increases, b decreases
                    let idx = b as i32;
                    let g = interpolate(idx, 0x20, 0x7E, 128, 255);
                    let bc = interpolate(idx, 0x20, 0x7E, 255, 100);
                    Color::Rgb(0, g, bc)
                }
                _ => {
                    // 0x80..0xFF: red-yellow-white
                    let idx = b as i32;
                    let r = 255u8;
                    let g = interpolate(idx, 0x80, 0xFF, 0, 255);
                    let bc = interpolate(idx, 0x80, 0xFF, 0, 255);
                    Color::Rgb(r, g, bc)
                }
            }
        }
    }
}

fn interpolate(x: i32, x0: i32, x1: i32, y0: i32, y1: i32) -> u8 {
    if x1 == x0 {
        return y0.clamp(0, 255) as u8;
    }
    let y = y0 + (y1 - y0) * (x - x0) / (x1 - x0);
    y.clamp(0, 255) as u8
}

fn write_char_panel<W: Write>(
    out: &mut W,
    bytes: &[u8],
    layout: &Layout,
    cfg: &ColorConfig,
    args: &Args,
) -> io::Result<()> {
    let width = layout.char_panel_width;
    let mut last_color: Option<Color> = None;
    let mut color_active = false;
    for i in 0..width {
        if i < bytes.len() {
            let b = bytes[i];
            let cat = categorize(b);
            let color = color_for_byte(b, cat, args, cfg);
            if cfg.active {
                if Some(&color) != last_color.as_ref() {
                    out.write_all(color.escape().as_bytes())?;
                    last_color = Some(color);
                    color_active = true;
                }
            }
            let ch = byte_to_display_char(b, args.character_table);
            // Always output one char
            let mut buf = [0u8; 4];
            let s = ch.encode_utf8(&mut buf);
            out.write_all(s.as_bytes())?;
        } else {
            out.write_all(b" ")?;
        }
    }
    if cfg.active && color_active {
        out.write_all(b"\x1b[39m")?;
    }
    Ok(())
}

fn byte_to_display_char(b: u8, table: CharTable) -> char {
    match table {
        CharTable::Default => match b {
            0x00 => '\u{22C4}',  // ⋄
            0x20 => ' ',
            0x09 | 0x0A | 0x0C | 0x0D => '_',
            0x21..=0x7E => b as char,
            0x80..=0xFF => '×',
            _ => '•',
        },
        CharTable::Ascii => match b {
            0x20 => ' ',
            0x21..=0x7E => b as char,
            _ => '.',
        },
        CharTable::Codepage437 => cp437::char_for(b),
        CharTable::Codepage1047 => cp1047::char_for(b),
        CharTable::Braille => match b {
            0x00 => '\u{22C4}',
            0x09 => '\u{2192}',  // →
            0x0A => '\u{21B5}',  // ↵
            0x0D => '\u{2190}',  // ←
            0x20..=0x7E => b as char,
            _ => {
                let bits = braille_bit_remap(b);
                char::from_u32(0x2800 + bits as u32).unwrap_or('.')
            }
        }
    }
}

fn braille_bit_remap(b: u8) -> u8 {
    // byte bits -> braille bits:
    // 0->0, 1->3, 2->1, 3->4, 4->2, 5->5, 6->6, 7->7
    (b & 0x01)
        | ((b & 0x02) << 2)
        | ((b & 0x04) >> 1)
        | ((b & 0x08) << 1)
        | ((b & 0x10) >> 2)
        | (b & 0x20)
        | (b & 0x40)
        | (b & 0x80)
}
