                }
                0x20..=0x7E => {
                    let x = (b as u32) - 0x20;
                    let g_off = (x * 127) / 94;
                    let b_off = ceil_div(x * 127, 94);
                    let g = 128 + g_off;
                    let bc = 255u32.saturating_sub(b_off);
