cd $(pwd) && cat > src/parse_num.rs <<'EOF'
// Parse byte counts with unit suffixes
#[derive(Debug)]
pub struct ParseError {
    pub msg: String,
    pub sub_causes: Option<Vec<String>>,
}

impl ParseError {
    fn simple(s: impl Into<String>) -> Self {
        ParseError { msg: s.into(), sub_causes: None }
    }
    fn with_subs(s: impl Into<String>, sub: Vec<String>) -> Self {
        ParseError { msg: s.into(), sub_causes: Some(sub) }
    }
}

fn unit_multiplier(unit_orig: &str, block_size: u64) -> Option<u64> {
    let u = unit_orig.to_ascii_lowercase();
    match u.as_str() {
        "" => Some(1),
        "block" | "blocks" => Some(block_size),
        "kb" => Some(1000),
        "kib" => Some(1024),
        "mb" => Some(1_000_000),
        "mib" => Some(1024u64 * 1024),
        "gb" => Some(1_000_000_000),
        "gib" => Some(1024u64 * 1024 * 1024),
        "tb" => Some(1_000_000_000_000),
        "tib" => Some(1024u64 * 1024 * 1024 * 1024),
        _ => None,
    }
}

// Parse with error context used for --length, --display-offset, positive --skip, --block-size
pub fn parse_byte_count(s: &str, block_size: u64) -> Result<u64, ParseError> {
    if s.starts_with('-') {
        return Err(ParseError::simple("negative offset specified, but only positive offsets (counts) are accepted in this context"));
    }
    parse_byte_count_internal(s, block_size)
}

pub fn parse_byte_count_allow_any(s: &str, block_size: u64) -> Result<u64, ParseError> {
    parse_byte_count_internal(s, block_size)
}

fn parse_byte_count_internal(s: &str, block_size: u64) -> Result<u64, ParseError> {
    if s.is_empty() {
        return Err(ParseError::simple(format!("\"{}\" is not of the expected form <pos-integer>[<unit>]", s)));
    }
    // Check for hex prefix
    if s.starts_with("0x") || s.starts_with("0X") {
        // Try stripping a valid unit suffix, then parse remainder as hex.
        let (num_str, unit) = split_unit_at_end(s);
        let hex_part = &num_str[2..]; // strip "0x"
        if hex_part.is_empty() {
            return Err(ParseError::with_subs(
                "failed to parse integer part",
                vec!["failed to parse integer part".into(), "cannot parse integer from empty string".into()],
            ));
        }
        if !hex_part.chars().all(|c| c.is_ascii_hexdigit()) {
            return Err(ParseError::with_subs(
                "failed to parse integer part",
                vec!["failed to parse integer part".into(), "invalid digit found in string".into()],
            ));
        }
        let n = u64::from_str_radix(hex_part, 16).map_err(|_| {
            ParseError::with_subs(
                "failed to parse integer part",
                vec!["failed to parse integer part".into(), "invalid digit found in string".into()],
            )
        })?;
        if let Some(m) = unit_multiplier(unit, block_size) {
            Ok(n.saturating_mul(m))
        } else {
            Err(ParseError::simple(format!("invalid unit \"{}\"", unit)))
        }
    } else {
        // Decimal: parse leading digits
        let mut i = 0;
        let bytes = s.as_bytes();
